def _add_complex_section(self, item):
        """Add a section that has a filter and set of constraints

        :raise: ValueError if filter or constraints is missing
        """
        if "filter" not in item:
            raise ValueError(
                "Complex section %s must contain a filter" % item["name"]
            )
        if "constraints" not in item:
            raise ValueError(
                "Complex section %s must contain constraints" % item["name"]
            )
        filter_item = item["filter"]
        self.add_filter(filter_item["name"], filter_item["type"])
        for constraint in item["constraints"]:
            self.add_constraint(constraint)

